CREATE OR REPLACE FUNCTION public.eliminar_socio_admin(p_actor uuid,p_socio uuid,p_nombre text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; u uuid; otros boolean; BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=p_actor AND rol='super_admin' AND activo) THEN RAISE EXCEPTION 'Solo Super admin'; END IF; SELECT * INTO s FROM public.socios WHERE id=p_socio FOR UPDATE; IF NOT FOUND OR s.nombre IS DISTINCT FROM p_nombre THEN RAISE EXCEPTION 'Escribe el nombre completo'; END IF; SELECT id INTO u FROM auth.users WHERE lower(email)=lower(s.email); IF u=p_actor OR EXISTS(SELECT 1 FROM public.usuario_roles WHERE socio_id=p_socio AND user_id=p_actor) THEN RAISE EXCEPTION 'No puedes eliminarte a ti mismo'; END IF; PERFORM set_config('club.test_write','yes',true); UPDATE public.visitas SET socio_id=null,socio_eliminado=true WHERE socio_id=p_socio; DELETE FROM public.avisos_leidos WHERE socio_id=p_socio; DELETE FROM public.pagos WHERE socio_id=p_socio; DELETE FROM public.usuario_vista WHERE role_id IN(SELECT id FROM public.usuario_roles WHERE (socio_id=p_socio OR email=lower(s.email)) AND rol='socia'); DELETE FROM public.usuario_roles WHERE (socio_id=p_socio OR email=lower(s.email)) AND rol='socia'; UPDATE public.usuario_roles SET socio_id=null WHERE socio_id=p_socio; DELETE FROM public.user_roles WHERE user_id=u AND role='socia'; UPDATE public.profiles SET socio_id=null WHERE socio_id=p_socio; DELETE FROM public.solicitudes_socios WHERE socio_id=p_socio; DELETE FROM public.equipo_invitaciones WHERE socio_id=p_socio; SELECT EXISTS(SELECT 1 FROM public.usuario_roles WHERE (user_id=u OR email=lower(s.email)) AND activo AND rol IN ('directiva','negocio','super_admin')) INTO otros; IF NOT otros THEN DELETE FROM public.avisos_leidos WHERE user_id=u; DELETE FROM public.usuario_vista WHERE user_id=u OR role_id IN(SELECT id FROM public.usuario_roles WHERE user_id=u OR email=lower(s.email)); DELETE FROM public.usuario_roles WHERE user_id=u OR email=lower(s.email); END IF; DELETE FROM public.socios WHERE id=p_socio; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(p_actor,u,'eliminar_socio',s.nombre||' · nº '||s.numero_socio); RETURN jsonb_build_object('usuario',u,'borrar_auth',NOT otros AND u IS NOT NULL); END $$;